    private static let byID: [String: Service] = Dictionary(all.map { ($0.id, $0) }, uniquingKeysWith: { a, _ in a })

    public static func service(id: String) -> Service? { byID[id] }

    /// The service a website belongs to: github.com, gist.github.com and api.github.com are all GitHub.
    public static func service(forHost host: String) -> Service? {
        let host = host.lowercased().trimmingCharacters(in: CharacterSet(charactersIn: "."))
        var best: (Service, Int)?
        for s in all {
            for d in s.domains where host == d || host.hasSuffix("." + d) {
                if d.count > (best?.1 ?? 0) { best = (s, d.count) }
            }
        }
        return best?.0
    }

    /// The service a name points to: "GITHUB_TOKEN", "Stripe live key", "Hugging Face". The longest match wins,
    /// so "Google Cloud" beats "Google" and "GitHub Actions" beats "GitHub".
    public static func service(named text: String) -> Service? {
        let words = text.lowercased().split(whereSeparator: { !$0.isLetter && !$0.isNumber }).map(String.init)
        guard !words.isEmpty else { return nil }
        let set = Set(words)
        let spaced = " " + words.joined(separator: " ") + " "
        let compact = words.joined()
        var best: (Service, Int)?
        for s in all {
            for term in terms[s.id] ?? [] {
                let parts = term.split(separator: " ")
                let hit: Bool
                if parts.count > 1 {
                    hit = spaced.contains(" " + term + " ") || compact.contains(parts.joined())
                } else {
                    // Whole words, or inside a run-together name ("GitHubToken") for longer names.
                    hit = set.contains(term) || (term.count >= 6 && compact.contains(term))
                }
                if hit, term.count > (best?.1 ?? 0) { best = (s, term.count) }
            }
        }
        return best?.0
    }

    /// Best guess for an item, from what the person typed (never the value): the link's site first, then
    /// the detected provider, then the name and where it's from, then any website mentioned in the note.
    public static func match(name: String, from: String? = nil, provider: String? = nil,
                             link: String? = nil, note: String? = nil) -> Service? {
        if let host = Links.host(of: link), let s = service(forHost: host) { return s }
        for text in [provider, from] {
            if let text, let host = host(in: text), let s = service(forHost: host) { return s }
        }
        for text in [provider, name, from].compactMap({ $0 }) {
            if let s = service(named: text) { return s }
        }
        if let note, let host = host(in: note), let s = service(forHost: host) { return s }
        return nil
    }

    /// The first thing that looks like a website ("github.com", "https://dash.cloudflare.com/…").
    static func host(in text: String) -> String? {
        guard let r = text.lowercased().range(of: #"\b[a-z0-9-]+(\.[a-z0-9-]+)*\.[a-z]{2,}\b"#, options: .regularExpression) else { return nil }
        return String(text.lowercased()[r])
    }

    private static let terms: [String: [String]] = Dictionary(all.map { s in
        (s.id, Array(Set([s.id, s.name.lowercased()] + s.aliases.map { $0.lowercased() })).filter { $0.count >= 2 })
    }, uniquingKeysWith: { a, _ in a })
}
